'use client';

import {
  ArrowDownToLine,
  Bookmark,
  BookmarkCheck,
  Check,
  Clipboard,
  ClipboardCheck,
  Copy,
  Download,
  FileCheck,
  Heart,
  HeartPulse,
  History,
  ListFilter,
  ListFilterPlus,
  LoaderCircle,
  LockKeyhole,
  LockOpen,
  Moon,
  Pause,
  Play,
  RefreshCw,
  Save,
  Send,
  SendHorizontal,
  Sun,
  Volume2,
  VolumeX,
  type IconNode,
} from 'lucide';
import { MorphIcon } from 'morphicons/react';
import * as React from 'react';

import { cn } from '@/lib/utils';

import styles from './micro-buttons.module.css';

type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement>;

function HoverMorphIcon({
  className,
  hoverIcon,
  icon,
}: {
  className?: string;
  hoverIcon: IconNode;
  icon: IconNode;
}) {
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const [hovered, setHovered] = React.useState(false);

  React.useEffect(() => {
    const root = rootRef.current;
    const button = root?.closest('button');
    const canHover = window.matchMedia('(hover: hover) and (pointer: fine)');
    if (!button || !canHover.matches) return;

    const enter = () => {
      if (!(button instanceof HTMLButtonElement) || !button.disabled)
        setHovered(true);
    };
    const leave = () => setHovered(false);
    const commit = () => setHovered(false);
    button.addEventListener('pointerenter', enter);
    button.addEventListener('pointerleave', leave);
    button.addEventListener('click', commit);
    return () => {
      button.removeEventListener('pointerenter', enter);
      button.removeEventListener('pointerleave', leave);
      button.removeEventListener('click', commit);
    };
  }, []);

  return (
    <span
      ref={rootRef}
      className={cn(styles.morphIcon, className)}
      aria-hidden="true"
    >
      <MorphIcon
        icon={hovered ? hoverIcon : icon}
        reducedMotion="user"
        size={18}
        spring="snappy"
        strokeWidth={1.65}
      />
    </span>
  );
}

export type CopyButtonProps = Omit<ButtonProps, 'onCopy'> & {
  copiedLabel?: string;
  label?: string;
  onCopy?: () => void | Promise<void>;
  resetDelay?: number;
  text?: string;
};

export const CopyButton = React.forwardRef<HTMLButtonElement, CopyButtonProps>(
  function CopyButton(
