        resetTimer.current = setTimeout(
          () => setCopied(false),
          Math.max(resetDelay, 500),
        );
      } catch {
        setCopied(false);
      }
    }

    return (
      <button
        ref={ref}
        aria-label={copied ? copiedLabel : label}
