            : status === 'complete'
              ? ClipboardCheck
              : Download
        }
      />
      <span className={styles.downloadProgress} aria-hidden="true" />
      <span className={styles.downloadLabels} aria-hidden="true">
        <span>{label}</span>
        <span>{downloadingLabel}</span>
        <span>{completeLabel}</span>
