  transform: translateY(42%) scaleX(0.82);
}

.saveButton[data-state='pending'] .saveDot {
  opacity: 0.35;
  transform: scale(0.92);
}

.saveButton[data-state='complete'] {
  color: #bff1d4;
  background: #132019;
}

.saveButton[data-state='complete'] .saveIcon > svg:first-child {
  opacity: 0;
  transform: translateY(24%) scale(0.94);
}

.saveButton[data-state='complete'] .saveIcon > svg:last-child {
  opacity: 1;
  transform: scale(1);
}

.saveButton[data-state='pending'] .saveLabels span:first-child,
.saveButton[data-state='complete'] .saveLabels span:first-child,
.saveButton[data-state='complete'] .saveLabels span:nth-child(2) {
  opacity: 0;
  transform: rotateX(72deg);
}

.saveButton[data-state='pending'] .saveLabels span:nth-child(2),
.saveButton[data-state='complete'] .saveLabels span:nth-child(3) {
  opacity: 1;
  transform: rotateX(0deg);
}

.morphIcon {
  position: relative;
  display: grid;
  width: 18px;
  height: 18px;
  flex: 0 0 auto;
  place-items: center;
}

.morphIcon > svg,
.copyButton[data-state] .morphIcon > svg,
.downloadButton[data-state] .morphIcon > svg,
.likeButton[data-state] .morphIcon > svg,
.muteButton[data-state] .morphIcon > svg,
.refreshButton[data-state] .morphIcon > svg,
.sendButton[data-state] .morphIcon > svg,
.saveButton[data-state] .morphIcon > svg,
.themeButton[data-state] .morphIcon > svg {
  position: relative;
  width: 18px;
  height: 18px;
  fill: none;
  opacity: 1;
  transform: none;
}

.copyButton,
.muteButton,
.downloadButton,
.likeButton,
.themeButton,
.refreshButton,
.bookmarkButton,
.playButton,
.filterButton,
.sendButton,
.saveButton {
  transition:
    border-color 140ms ease,
    color 140ms ease,
    background-color 140ms ease,
    box-shadow 140ms ease,
    transform 200ms var(--micro-orbit-ease);
}

.copyButton > .morphIcon,
.copyButton > .copyLabels,
.likeButton > .morphIcon,
.likeButton > .likeLabels,
.playButton > .morphIcon,
.playButton > .playLabels,
.sendButton > .morphIcon,
.sendButton > .sendLabels,
.saveButton > .morphIcon,
.saveButton > .saveLabels {
  transition: transform 200ms var(--micro-orbit-ease);
}

.downloadButton[data-state='downloading'] .morphIcon > svg,
.refreshButton[data-state='refreshing'] .morphIcon > svg {
  animation: refresh-spin 720ms linear infinite;
}

@media (hover: hover) and (pointer: fine) {
  .button:hover:not(:disabled) {
    border-color: rgb(255 255 255 / 19%);
    background-color: #1d1e1a;
    box-shadow:
      inset 0 1px rgb(255 255 255 / 9%),
      0 10px 28px rgb(0 0 0 / 24%);
  }

  .lockButton:hover:not(:disabled) {
    transform: scaleX(1.075);
  }

  .lockButton:hover:not(:disabled) > .morphIcon,
  .lockButton:hover:not(:disabled) > .lockLabels {
    transform: scaleX(0.93);
  }

  .lockButton:hover:active:not(:disabled) {
    transform: scaleX(1.035) scaleY(0.97);
    transition-duration: 120ms;
  }

  .lockButton:hover:active:not(:disabled) > .morphIcon,
  .lockButton:hover:active:not(:disabled) > .lockLabels {
    transform: scaleX(0.966) scaleY(1.031);
    transition-duration: 120ms;
  }

  .copyButton:hover:not(:disabled) {
    transform: scaleX(1.055);
  }

  .copyButton:hover:not(:disabled) > .morphIcon,
  .copyButton:hover:not(:disabled) > .copyLabels {
    transform: scaleX(0.948);
  }

  .muteButton:hover:not(:disabled) {
    transform: translateY(-1px) rotate(-1.25deg);
  }

  .downloadButton:hover:not(:disabled) {
    transform: translateY(2px) scaleY(0.985);
  }

  .likeButton:hover:not(:disabled) {
    transform: scale(1.04);
  }

  .likeButton:hover:not(:disabled) > .morphIcon,
  .likeButton:hover:not(:disabled) > .likeLabels {
    transform: scale(0.962);
  }

  .themeButton:hover:not(:disabled) {
    transform: translateY(-1px) rotate(1.5deg);
  }

  .refreshButton:hover:not(:disabled) {
    transform: rotate(1.5deg) scale(1.015);
  }

  .bookmarkButton:hover:not(:disabled) {
    transform: translateY(-2px) scaleY(1.02);
  }

  .playButton:hover:not(:disabled) {
    transform: scaleX(1.055);
  }

  .playButton:hover:not(:disabled) > .morphIcon,
  .playButton:hover:not(:disabled) > .playLabels {
    transform: scaleX(0.948);
  }

  .filterButton:hover:not(:disabled) {
    transform: translateX(2px) skewX(-1.5deg);
  }

  .sendButton:hover:not(:disabled) {
    transform: translateX(3px) scaleX(1.025);
  }

  .sendButton:hover:not(:disabled) > .morphIcon,
  .sendButton:hover:not(:disabled) > .sendLabels {
    transform: scaleX(0.976);
  }

  .saveButton:hover:not(:disabled) {
    transform: translateY(-2px) scaleX(1.025);
  }

  .saveButton:hover:not(:disabled) > .morphIcon,
  .saveButton:hover:not(:disabled) > .saveLabels {
    transform: scaleX(0.976);
  }

  .copyButton:hover:active:not(:disabled),
  .playButton:hover:active:not(:disabled) {
    transform: scaleX(1.025) scaleY(0.97);
    transition-duration: 120ms;
  }

  .copyButton:hover:active:not(:disabled) > .morphIcon,
  .copyButton:hover:active:not(:disabled) > .copyLabels,
  .playButton:hover:active:not(:disabled) > .morphIcon,
  .playButton:hover:active:not(:disabled) > .playLabels {
    transform: scaleX(0.976) scaleY(1.031);
    transition-duration: 120ms;
  }

  .muteButton:hover:active:not(:disabled),
  .downloadButton:hover:active:not(:disabled),
  .likeButton:hover:active:not(:disabled),
  .themeButton:hover:active:not(:disabled),
  .refreshButton:hover:active:not(:disabled),
  .bookmarkButton:hover:active:not(:disabled),
  .filterButton:hover:active:not(:disabled),
  .sendButton:hover:active:not(:disabled),
  .saveButton:hover:active:not(:disabled) {
    transform: scale(0.97);
    transition-duration: 120ms;
  }

  .likeButton:hover:active:not(:disabled) > .morphIcon,
  .likeButton:hover:active:not(:disabled) > .likeLabels,
  .sendButton:hover:active:not(:disabled) > .morphIcon,
  .sendButton:hover:active:not(:disabled) > .sendLabels,
  .saveButton:hover:active:not(:disabled) > .morphIcon,
  .saveButton:hover:active:not(:disabled) > .saveLabels {
    transform: none;
    transition-duration: 120ms;
  }
}

@keyframes download-progress {
  0% {
    opacity: 0;
    transform: scaleX(0.08);
  }

  18% {
    opacity: 0.58;
  }

  82% {
    opacity: 0.58;
  }

  100% {
    opacity: 0;
    transform: scaleX(1);
  }
}

@keyframes refresh-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .button,
  .button svg,
  .button span,
  .button path,
  .button::before,
  .button::after {
    transition-duration: 0ms;
  }

  .button:active {
    transform: none;
  }

  .lockButton:hover:not(:disabled),
  .lockButton:hover:not(:disabled) > .morphIcon,
  .lockButton:hover:not(:disabled) > .lockLabels {
    transform: none;
  }

  .button:hover:not(:disabled),
  .button:hover:active:not(:disabled),
  .button:hover:not(:disabled) > .morphIcon,
  .button:hover:active:not(:disabled) > .morphIcon,
  .button:hover:not(:disabled) > .copyLabels,
  .button:hover:active:not(:disabled) > .copyLabels,
  .button:hover:not(:disabled) > .likeLabels,
  .button:hover:active:not(:disabled) > .likeLabels,
  .button:hover:not(:disabled) > .lockLabels,
  .button:hover:active:not(:disabled) > .lockLabels,
  .button:hover:not(:disabled) > .playLabels,
  .button:hover:active:not(:disabled) > .playLabels,
  .button:hover:not(:disabled) > .sendLabels,
  .button:hover:active:not(:disabled) > .sendLabels,
  .button:hover:not(:disabled) > .saveLabels,
  .button:hover:active:not(:disabled) > .saveLabels {
    transform: none;
  }

  .downloadButton[data-state='downloading'] .downloadProgress {
    animation: none;
    opacity: 0.45;
    transform: scaleX(1);
  }

  .refreshButton[data-state='refreshing'] .refreshIcon svg:first-child {
    animation: none;
    opacity: 0.55;
  }

  .downloadButton[data-state='downloading'] .morphIcon > svg,
  .refreshButton[data-state='refreshing'] .morphIcon > svg {
    animation: none;
  }

  .bookmarkButton[data-state='bookmarked'] .bookmarkShape,
  .lockButton[data-state='locked'] .lockShackle,
  .playButton[data-state='playing'] .playTriangle,
  .playButton[data-state='playing'] .pauseBar,
  .filterButton[data-state='active'] .filterIcon b,
  .sendButton[data-state='pending'] .sendIcon > svg:first-child,
  .sendButton[data-state='complete'] .sendIcon > svg:first-child,
  .saveButton[data-state='pending'] .saveSlot,
  .saveButton[data-state='complete'] .saveIcon > svg:first-child {
    transform: none;
  }
}

@media (forced-colors: active) {
  .button,
  .copyButton[data-state='copied'],
  .bookmarkButton[data-state='bookmarked'],
  .downloadButton[data-state='complete'],
  .filterButton[data-state='active'],
  .likeButton[data-state='liked'],
  .lockButton[data-state='locked'],
  .muteButton[data-state='muted'],
  .playButton[data-state='playing'],
  .refreshButton[data-state='complete'],
  .saveButton[data-state='complete'],
  .sendButton[data-state='complete'],
  .themeButton[data-state='dark'] {
    border-color: ButtonText;
    color: ButtonText;
    background: ButtonFace;
    box-shadow: none;
  }
}

